import{_ as d,o as n,c as e,a2 as o}from"./chunks/framework.Dlbr0fgz.js";const m=JSON.parse('{"title":"Sounds / Âm thanh","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/sounds.md","filePath":"gdd/sounds.md"}'),c={name:"gdd/sounds.md"};function a(h,t,r,s,i,g){return n(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="sounds-am-thanh" tabindex="-1">Sounds / Âm thanh <a class="header-anchor" href="#sounds-am-thanh" aria-label="Permalink to &quot;Sounds / Âm thanh&quot;">​</a></h1><p><strong>Trạng thái (12/11):</strong> đã gắn xong toàn bộ file trong <code>Added Assets/Sound/Newly Added</code> (đổi sang m4a, để ở <code>public/sfx</code>). Âm nào không có file thì <strong>không phát</strong> (đã bỏ hết tiếng tổng hợp bằng code).</p><table tabindex="0"><thead><tr><th>Âm</th><th>File</th><th>Khi nào phát</th></tr></thead><tbody><tr><td>Combo</td><td><code>sfx_combo_word_1..4</code></td><td>Ngay lúc bấm cá đúng, từ cá thứ 2 trong chain: 1, 2, 3, 4 rồi giữ nguyên âm 4 cho đến khi gãy combo (chữ khen hiện đúng chỗ cá vừa bấm)</td></tr><tr><td>Bấm sai</td><td><code>sfx_bad</code></td><td>Cá sai hoặc vật cản đáp xuống Backup; nước tràn lúc thua</td></tr><tr><td>Bấm vào nước</td><td><code>sfx_tap_water</code></td><td>Bấm chỗ trống; ống bắt đầu rung</td></tr><tr><td>Ống mở / đóng</td><td><code>sfx_pipe_open</code> / <code>sfx_pipe_close</code></td><td>Ống sắp thả cá / thả xong hoặc tạm giữ</td></tr><tr><td>Nước bắn</td><td><code>sfx_splash</code></td><td>Cá nhảy ra khỏi mặt nước, cá rơi lại sau màn thắng, thả đá, ngọc trai chạm nước</td></tr><tr><td>Sò</td><td><code>sfx_clam_snap</code>, <code>sfx_clam_tap_open</code></td><td>Sò đớp cá; mỗi lần bấm sò và lúc sò mở (dùng chung một file)</td></tr><tr><td>Ngọc trai</td><td><code>sfx_pearl_bounce</code></td><td>Mỗi lần ngọc trai nảy</td></tr><tr><td>Thanh tiến độ</td><td><code>sfx_bubble_hit_gauge</code>, <code>sfx_gauge_fill</code></td><td>Bóng bay trúng thanh; thanh dâng lên (trễ 0,1 s)</td></tr><tr><td>Xoáy thắng</td><td><code>sfx_win_swirl</code></td><td>Lúc cá bắt đầu bơi xoắn trong màn thắng (T = 0,3 s)</td></tr><tr><td>Rèm</td><td><code>sfx_curtain_close</code> / <code>sfx_curtain_open</code></td><td>Rèm đóng sau màn thắng / rèm mở sang level mới</td></tr></tbody></table><p>Không dùng (chưa có file): swarm, squabble, conga, hide, feed, nhím/sứa, bounty, title pop, tutorial, kết quả, camera, đổi hình bể, ambience, <code>sfx_combo_step</code>.</p><hr><h1 id="reference-cho-toi-tra-cuu-ban-khong-can-đoc-inventory" tabindex="-1">Reference (cho tôi tra cứu, bạn không cần đọc) / Inventory <a class="header-anchor" href="#reference-cho-toi-tra-cuu-ban-khong-can-đoc-inventory" aria-label="Permalink to &quot;Reference (cho tôi tra cứu, bạn không cần đọc) / Inventory&quot;">​</a></h1><h2 id="đa-co-file-ghi-am-public-sfx" tabindex="-1">Đã có file ghi âm (public/sfx) <a class="header-anchor" href="#đa-co-file-ghi-am-public-sfx" aria-label="Permalink to &quot;Đã có file ghi âm (public/sfx)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Phát khi</th></tr></thead><tbody><tr><td>bgm_ap.m4a</td><td>Nhạc nền; chạy lại mỗi level, nhỏ đi khi có pop-up</td></tr><tr><td>ui_button_click.m4a</td><td>Mọi nút; cũng dùng cho bấm vào chỗ trống (miss)</td></tr><tr><td>sfx_fish_tap.m4a</td><td>Bấm đúng cá</td></tr><tr><td>sfx_fish_to_backup.m4a</td><td>Cá vào Backup</td></tr><tr><td>sfx_fish_to_tank_or_vice_versa.m4a</td><td>Cá vào bể đích / rút từ Backup; chữ khen hiện lúc cá vào bể. File này là tiếng vù/nước nên không đổi cao độ được (đã thử, không nghe ra; nốt chuông bằng code nghe dở nên bỏ)</td></tr><tr><td>sfx_fish_spawn.m4a</td><td>Ống đẩy cá ra</td></tr><tr><td>sfx_hint.m4a</td><td>Booster gợi ý</td></tr><tr><td>sfx_level_start.m4a</td><td>Bắt đầu level</td></tr><tr><td>sfx_squid.m4a</td><td>Mực phun mực</td></tr><tr><td>sfx_tank_complete.m4a</td><td>Hoàn thành một bể đích</td></tr><tr><td>sfx_win.m4a / sfx_lose.m4a</td><td>Thắng / thua (Out of Space! = thua)</td></tr><tr><td>sfx_backup_break.m4a</td><td>Kính Backup vỡ (thua)</td></tr><tr><td>sfx_popup_open.m4a / sfx_popup_close.m4a</td><td>Mở (Pause, Levels, Intro) / đóng pop-up; rèm màn thắng</td></tr><tr><td>sfx_play_on.m4a</td><td>Mở pop-up Play On</td></tr></tbody></table><h2 id="đang-la-tieng-tong-hop-bang-code" tabindex="-1">Đang là tiếng tổng hợp bằng code <a class="header-anchor" href="#đang-la-tieng-tong-hop-bang-code" aria-label="Permalink to &quot;Đang là tiếng tổng hợp bằng code&quot;">​</a></h2><p><code>scatter</code>, <code>splash</code>, <code>land</code>, <code>complete</code>, <code>good</code>, <code>bad</code>. Có định nghĩa nhưng không bao giờ phát: <code>junk</code>, <code>plip</code>, <code>start</code> (lệnh gọi nằm trong comment), <code>ambient()</code> (tắt).</p>',10)])])}const _=d(c,[["render",a]]);export{m as __pageData,_ as default};
